'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const all=BOOK.lessons.flatMap(l=>l.dialogues.map(d=>({...d,lesson:l.number}))), lookup=new Map(all.map(d=>[d.id,d]));
const dictionary=new Map(all.map(d=>[d.target,d.meaning])); const terms=[...dictionary.keys()].sort((a,b)=>b.length-a.length);
const KEY='hanzi-reading-room-v1';
function cleanState(raw){const s={version:1,last:'9-1',records:{},words:{}};if(!raw||raw.version!==1)return s;if(lookup.has(raw.last))s.last=raw.last;
 for(const [id,r] of Object.entries(raw.records||{})){if(!lookup.has(id)||!r||typeof r!=='object')continue;const p={reads:Math.max(0,Math.min(10000,Number(r.reads)||0)),independent:r.independent===true,passed:{}};for(const type of ['meaning','cloze','build'])p.passed[type]=r.passed?.[type]===true;s.records[id]=p;}
 for(const [word,w] of Object.entries(raw.words||{})){if(!dictionary.has(word)||!w||typeof w!=='object')continue;s.words[word]={stage:Math.max(0,Math.min(3,Number(w.stage)||0)),due:Number.isFinite(w.due)?w.due:0};}return s;}
let state;try{state=cleanState(JSON.parse(localStorage.getItem(KEY)));}catch{state=cleanState(null);}
let readingToolsOpen=false;const readingStage='read';
let current=lookup.get(state.last),mode='read',classOnly=false,help=false,spacing=false,large=false,type='meaning',exercise=null,selectedWord=null,usedPronunciation=false;
let dialogueDrafts={version:2,last:null,entries:{}};
try{const raw=JSON.parse(localStorage.getItem('hanzi-dialogue-drafts-v2'));if(raw?.version===2&&raw.entries&&typeof raw.entries==='object')dialogueDrafts=raw;}catch{}
function validDialogueDraft(d,kind,x){if(!d||!x||x.kind!==kind||typeof x.answered!=='boolean')return null;let valid=false;
 if(kind==='meaning')valid=Array.isArray(x.options)&&x.options.length===d.options.length&&new Set(x.options).size===x.options.length&&x.options.every(o=>d.options.includes(o));
 if(kind==='cloze')valid=d.lines.includes(x.line)&&Array.isArray(x.options)&&x.options.length===3&&new Set(x.options).size===3&&x.options.includes(d.target)&&x.options.every(o=>dictionary.has(o));
 if(kind==='build')valid=Array.isArray(x.chunks)&&x.chunks.length>0&&x.chunks.length<=10&&x.chunks.every(c=>typeof c==='string')&&d.lines.some(l=>l.split(/[。！？]/).some(t=>t.trim()===x.sentence))&&x.chunks.join('')===x.sentence&&Array.isArray(x.indices)&&x.indices.length===x.chunks.length&&new Set(x.indices).size===x.indices.length&&x.indices.every(i=>Number.isInteger(i)&&i>=0&&i<x.chunks.length)&&Array.isArray(x.chosen)&&new Set(x.chosen).size===x.chosen.length&&x.chosen.every(i=>Number.isInteger(i)&&i>=0&&i<x.chunks.length);
 if(!valid)return null;const out=JSON.parse(JSON.stringify(x));if(kind!=='build'&&x.selected!==undefined&&!x.options.includes(x.selected))return null;
 if(x.answered){if(kind==='build'){if(x.chosen.length!==x.chunks.length)return null;out.correct=x.chosen.map(i=>x.chunks[i]).join('')===x.sentence;}else{if(!x.options.includes(x.selected))return null;out.correct=x.selected===(kind==='meaning'?d.options[0]:d.target);}}return out;
}
function restoreDialogueDraft(id,kind){return validDialogueDraft(lookup.get(id),kind,dialogueDrafts.entries[id+':'+kind]);}
function stashDialogueDraft(){if(!exercise)return;dialogueDrafts.entries[current.id+':'+type]=exercise;dialogueDrafts.last={id:current.id,type};try{localStorage.setItem('hanzi-dialogue-drafts-v2',JSON.stringify(dialogueDrafts));localStorage.setItem('hanzi-dialogue-draft-v1',JSON.stringify({id:current.id,type,exercise}));}catch{}}
function record(id=current.id){return state.records[id]??=( {reads:0,independent:false,passed:{}});}
function save(){state.last=current.id;try{localStorage.setItem(KEY,JSON.stringify(state));$('#storage-status').textContent='';}catch{$('#storage-status').textContent='Browser storage is unavailable. Export progress to keep it.';}updateStats();}
let toastTimer;function toast(s){$('#toast').textContent=s;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').textContent='',3200);}
function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function updateStats(){const n=Object.values(state.records).filter(r=>r.reads>0).length;$('#book-progress').value=n;$('#book-count').textContent=`${n} of 60 dialogues read`;}
function renderLessons(){const q=$('#search').value.trim().toLowerCase();const list=BOOK.lessons.filter(l=>(!classOnly||l.number>=9)&&(!q||`${l.number} ${l.title} ${l.dialogues.map(d=>d.lines.join('')).join('')}`.toLowerCase().includes(q)));$('#lesson-list').innerHTML=list.length?list.map(l=>{const read=l.dialogues.filter(d=>state.records[d.id]?.reads>0).length;return `<button class="lesson-button ${current.lesson===l.number?'selected':''}" data-lesson="${l.number}" ${current.lesson===l.number?'aria-current="true"':''}><span class="lesson-number">${String(l.number).padStart(2,'0')}</span><span><strong lang="zh-Hans">${l.title}</strong><small>${read}/4 read ${l.number>=9?'· YOUR CLASS':''}</small></span></button>`;}).join(''):'<p class="empty">No matching lessons.</p>';$$('[data-lesson]').forEach(b=>b.onclick=()=>choose(`${b.dataset.lesson}-1`));}
function choose(id){stashDialogueDraft();type='meaning';current=lookup.get(id);mode='read';exercise=null;selectedWord=null;help=false;usedPronunciation=false;state.last=id;save();render();}
function wordMarkup(line,lineIndex){const phonetics=current.pronunciation?.[lineIndex]||[];const annotate=(text,offset,insideButton=false)=>[...text].map((c,j)=>/\p{Script=Han}/u.test(c)&&phonetics[offset+j]?`<span class="hanzi-char" data-pinyin="${escapeHTML(phonetics[offset+j])}" tabindex="${insideButton?-1:0}" aria-label="${c}: ${escapeHTML(phonetics[offset+j])}">${c}</span>`:escapeHTML(c)).join('');
 if(!help&&!spacing)return annotate(line,0);let html='',i=0;while(i<line.length){const t=terms.find(t=>line.startsWith(t,i));if(t){html+=`<button class="word ${spacing?'spaced':''}" data-word="${escapeHTML(t)}" aria-label="Meaning of ${escapeHTML(t)}">${annotate(t,i,true)}</button>`;i+=t.length;}else{html+=annotate(line[i],i);i++;}}return html;}

function render(){window.HanziVoice?.stop();renderLessons();updateStats();$('#nav-read').classList.toggle('active',mode==='read');
 const l=BOOK.lessons[current.lesson-1],r=record(),done=Object.values(r.passed).filter(Boolean).length;$('#workspace').dataset.stage=readingStage;try{localStorage.setItem('hanzi-reading-stage',JSON.stringify({id:current.id,stage:readingStage}));}catch{}
 $('#workspace').innerHTML=`<div class="lesson-heading"><div><span class="chapter-label">LESSON ${String(l.number).padStart(2,'0')} ${l.number>=9?' / YOUR CLASS':''}</span><h2 lang="zh-Hans">${l.title}</h2><p>LESSON ${l.number} / 15 <span class="room-dot">·</span> DIALOGUE ${current.number} / 4</p></div><button id="next-lesson" ${l.number===15?'disabled':''}>Next lesson ↗</button></div>
 <article class="reader-card" data-recording="${current.id}"><div class="dialogue-tabs" role="tablist" aria-label="Dialogue"><!-- tabs -->${l.dialogues.map(d=>`<button role="tab" aria-selected="${d.id===current.id}" class="${d.id===current.id?'selected':''}" data-dialogue="${d.id}">对话 ${d.number} ${state.records[d.id]?.reads?'✓':''}</button>`).join('')}</div>
 <div class="card-top"><div><span class="scene" lang="zh-Hans">${current.scene}</span><span class="page-ref">TEXT ${current.lesson}.${current.number} · Book p. ${current.bookPage} · PDF p. ${current.page}</span></div><details class="reading-options" ${readingToolsOpen?'open':''}><summary>Reading tools</summary><div class="tool-row"><button id="word-help" aria-pressed="${help}">Word help ${help?'on':'off'}</button><button id="word-spacing" aria-pressed="${spacing}">Word spacing ${spacing?'on':'off'}</button><button id="text-size" aria-pressed="${large}">大 Text size</button></div></details></div>
 <div class="conversation" id="dialogue-text" lang="zh-Hans" style="${large?'--reading-size:32px':''}">${current.lines.map((line,i)=>`<div class="turn"><span class="speaker">${current.speakers[i]}</span><div class="hanzi">${wordMarkup(line,i)}</div></div>`).join('')}</div>
 ${selectedWord?`<div class="vocab-panel"><div><b lang="zh-Hans">${selectedWord}</b><span>${escapeHTML(dictionary.get(selectedWord))}</span></div><button id="close-word" aria-label="Close word meaning">×</button></div>`:''}
 <div class="reading-bottom"><div><p>${r.reads?`Read ${r.reads} time${r.reads===1?'':'s'} · ${r.independent?'Last read: without help':'Last read: with help'}`:'Hover over dialogue characters for pinyin.'}</p><p>${spacing?'Spacing marks the collection’s focus words only. Return to normal spacing for your next read.':'Read the whole sentence before looking up a word.'}</p></div><button id="mark-read" class="primary">Finish & next dialogue →</button></div></article>
 `;
 $$('[data-dialogue]').forEach(b=>b.onclick=()=>choose(b.dataset.dialogue));$('#next-lesson').onclick=()=>choose(`${l.number+1}-1`);
 $('#word-help').onclick=()=>{help=!help;if(!help)selectedWord=null;render();};$('#word-spacing').onclick=()=>{spacing=!spacing;render();};$('#text-size').onclick=()=>{large=!large;render();};$('#workspace .reading-options').ontoggle=e=>readingToolsOpen=e.target.open;
 $$('.hanzi-char').forEach(el=>{el.onmouseenter=()=>{usedPronunciation=true;};el.onfocus=()=>{usedPronunciation=true;};});
 $$('[data-word]').forEach(b=>b.onclick=()=>{selectedWord=b.dataset.word;render();});if(selectedWord){$('#close-word').onclick=()=>{selectedWord=null;render();};}
 $('#mark-read').onclick=()=>{const r=record();r.reads++;r.independent=!help&&!spacing&&!usedPronunciation;save();choose(all[(all.findIndex(d=>d.id===current.id)+1)%all.length].id);document.querySelector('#workspace').scrollIntoView({behavior:'smooth',block:'start'});};
 window.HanziVoice?.mount(current.id);}

$('#search').oninput=renderLessons;$('#all-filter').onclick=()=>{classOnly=false;$('#all-filter').classList.add('selected');$('#class-filter').classList.remove('selected');renderLessons();};$('#class-filter').onclick=()=>{classOnly=true;$('#class-filter').classList.add('selected');$('#all-filter').classList.remove('selected');if(current.lesson<9)choose('9-1');else renderLessons();};$('#nav-read').onclick=()=>{mode='read';render();};$('#nav-method').onclick=()=>$('#method').showModal();$('#method .close').onclick=()=>$('#method').close();
window.importReadingProgress=function(raw){if(raw?.version!==1||!raw.records||!raw.words)throw Error('format');const imported=cleanState(raw);for(const [id,r] of Object.entries(imported.records)){const old=state.records[id];if(old){r.reads=Math.max(r.reads,old.reads);for(const t of ['meaning','cloze','build'])r.passed[t]=r.passed[t]||old.passed[t];}state.records[id]=r;}Object.assign(state.words,imported.words);if(raw.drafts?.version===2&&raw.drafts.entries){for(const [key,x]of Object.entries(raw.drafts.entries)){const split=key.lastIndexOf(':'),id=key.slice(0,split),kind=key.slice(split+1),valid=validDialogueDraft(lookup.get(id),kind,x);if(valid)dialogueDrafts.entries[key]=valid;}exercise=restoreDialogueDraft(current.id,type);stashDialogueDraft();}save();render();};
$('#export-progress').onclick=async()=>{if(window.HanziPractice?.ready)await window.HanziPractice.ready;if(window.HanziPaper?.ready)await window.HanziPaper.ready;const full=window.HanziPractice?{format:'hanzi-full-progress',version:1,reading:{...state,drafts:dialogueDrafts},practice:window.HanziPractice.snapshot(),paper:window.HanziPaper?.snapshot()}:state;const blob=new Blob([JSON.stringify(full,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='hanzi-full-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};
$('#import-progress').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{const raw=JSON.parse(await file.text());if(raw.format==='hanzi-full-progress'&&window.HanziPractice)await window.HanziPractice.importBackup(file);else{window.importReadingProgress(raw);toast('Reading progress imported and merged.');}}catch{toast('Could not import that progress file.');}e.target.value='';};
// Recover legacy attempts and the last independently saved activity.
try{const old=JSON.parse(localStorage.getItem('hanzi-dialogue-draft-v1'));if(old&&validDialogueDraft(lookup.get(old.id),old.type,old.exercise)&&!dialogueDrafts.entries[old.id+':'+old.type]){dialogueDrafts.entries[old.id+':'+old.type]=old.exercise;if(!dialogueDrafts.last)dialogueDrafts.last={id:old.id,type:old.type};}}catch{}
if(dialogueDrafts.last?.id===current.id&&['meaning','cloze','build'].includes(dialogueDrafts.last.type))type=dialogueDrafts.last.type;
exercise=restoreDialogueDraft(current.id,type);
render();
